/**
 * UI/Components/ItemFinder/ItemFinder.js
 *
 * Turoran Item Finder: search weapons / armor / cards by stats and effects.
 * Data: System/itemfinder.turoran.v8.json (generated by turoran-ro-grf generators/genitemfinder.py)
 */

import DB from 'DB/DBManager.js';
import Client from 'Core/Client.js';
import KEYS from 'Controls/KeyEventHandler.js';
import GUIComponent from 'UI/GUIComponent.js';
import UIManager from 'UI/UIManager.js';
import Session from 'Engine/SessionStorage.js';
import 'UI/Elements/Elements.js';
import htmlText from './ItemFinder.html?raw';
import cssText from './ItemFinder.css?raw';

const DATA_FILE = 'System/itemfinder.turoran.v8.json';
const SOURCES_FILE = 'System/itemsources.turoran.v3.json';
const RMS_URL = id => `https://ratemyserver.net/index.php?page=re_item_db&item_id=${id}`;
const PAGE = 60;
const KINDS = [
	['damage', '% Damage'],
	['atk', 'ATK/MATK (flat)'],
	['resist', '% Resist'],
	['str', 'STR'],
	['agi', 'AGI'],
	['vit', 'VIT'],
	['int', 'INT'],
	['dex', 'DEX'],
	['luk', 'LUK'],
	['allstats', 'All Stats'],
	['def', 'DEF'],
	['def%', 'DEF %'],
	['mdef', 'MDEF'],
	['mdef%', 'MDEF %'],
	['hp', 'MaxHP'],
	['hp%', 'MaxHP %'],
	['sp', 'MaxSP'],
	['sp%', 'MaxSP %'],
	['regen', 'HP/SP Regen %'],
	['onkill', 'HP/SP per kill'],
	['aspd', 'ASPD'],
	['aspd%', 'ASPD %'],
	['cast', 'Cast %'],
	['castms', 'Cast/Cooldown (ms)'],
	['delay', 'After-cast Delay %'],
	['crit', 'Crit'],
	['hitflee', 'Hit/Flee'],
	['hitflee%', 'Hit/Flee %'],
	['heal', 'Heal'],
	['autospell', 'Autospell/Proc'],
	['other', 'Other']
];

const ItemFinder = new GUIComponent('ItemFinder', cssText);
ItemFinder.render = () => htmlText;

let _items = null;
let _byId = null;
let _loading = false;
let _cat = 'weapon';
let _page = 0;
let _results = [];
// Effect filter active -> default sort is matched-effect magnitude, desc. The sort the user had before
// the filter is restored when the filter is cleared; an explicit sort pick while filtering is respected.
let _effSortAuto = false;
let _savedSort = null;

function magOf(e) {
	// m: generator magnitude (bigger = better; refine/level formulas evaluated at +10 / Lv175); v: legacy fallback
	return typeof e.m === 'number' ? e.m : typeof e.v === 'number' ? e.v : null;
}

function stripItemNavi(s) {
	// Keep the label from navigation link tags. Navigation is off.
	return String(s).replace(/<NAVI>(.*?)<INFO>.*?<\/INFO><\/NAVI>/gi, '$1');
}

function esc(s) {
	return String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
}

function mdefOf(it) {
	let m = 0;
	for (const e of it.eff) if (e.k === 'mdef' && e.t === 'MDEF' && typeof e.v === 'number') m += e.v;
	return m;
}

function loadData(cb) {
	if (_items) return cb();
	if (_loading) return;
	_loading = true;
	setStatus('Loading item data...');
	Client.getFile(
		DATA_FILE,
		data => {
			try {
				const txt =
					typeof data === 'string'
						? data
						: new TextDecoder('utf-8').decode(data instanceof ArrayBuffer ? new Uint8Array(data) : data);
				_items = JSON.parse(txt).items;
				_byId = new Map(_items.map(it => [it.id, it]));
				for (const it of _items) {
					it._mdef = mdefOf(it);
					it._lc = (it.n + ' ' + (it.d ? it.d.map(l => l.x) : it.eff.map(e => e.x)).join(' ')).toLowerCase();
				}
			} catch (e) {
				setStatus('Failed to parse ' + DATA_FILE + ': ' + e.message);
			}
			_loading = false;
			cb();
		},
		() => {
			_loading = false;
			setStatus('Could not load ' + DATA_FILE);
		}
	);
}

function setStatus(t) {
	const root = ItemFinder.getRoot && ItemFinder.__loaded ? ItemFinder.getRoot() : null;
	if (root) root.querySelector('.status').textContent = t;
}

function fillSub() {
	const root = ItemFinder.getRoot();
	const sel = root.querySelector('.sub');
	const set = new Set();
	for (const it of _items || []) {
		if (it.c !== _cat) continue;
		if (_cat === 'weapon') set.add(it.wt);
		else for (const l of it.loc) set.add(l);
	}
	const label = {
		weapon: 'All weapon types',
		armor: 'All armor slots',
		card: 'All compound locations',
		enchant: 'All locations'
	}[_cat];
	sel.innerHTML =
		`<option value="">${label}</option>` +
		[...set]
			.sort()
			.map(v => `<option>${esc(v)}</option>`)
			.join('');
}

function matches(e, kinds, target) {
	if (kinds.size && !kinds.has(e.k)) return false;
	if (target && !(String(e.t).toLowerCase().includes(target) || e.x.toLowerCase().includes(target))) return false;
	return kinds.size > 0 || !!target;
}

ItemFinder.search = function search() {
	if (!_items) return;
	const root = this.getRoot();
	const q = root.querySelector('.q').value.trim().toLowerCase();
	const sub = root.querySelector('.sub').value;
	const target = root.querySelector('.target').value.trim().toLowerCase();
	const nocond = root.querySelector('.nocond').checked;
	const job = root.querySelector('.job').value.trim().toLowerCase();
	const lv = parseInt(root.querySelector('.lv').value, 10);
	const kinds = new Set([...root.querySelectorAll('.kinds input:checked')].map(i => i.value));
	const effFilter = kinds.size > 0 || !!target;
	const sortEl = root.querySelector('.sort');
	const dirEl = root.querySelector('.dir');
	if (effFilter && !_effSortAuto) {
		_effSortAuto = true;
		_savedSort = [sortEl.value, dirEl.value];
		sortEl.value = 'eff';
		dirEl.value = 'desc';
	} else if (!effFilter && _effSortAuto) {
		_effSortAuto = false;
		if (_savedSort && sortEl.value === 'eff') [sortEl.value, dirEl.value] = _savedSort;
		_savedSort = null;
	}
	const sort = sortEl.value;
	const dir = dirEl.value === 'asc' ? 1 : -1;

	const out = [];
	for (const it of _items) {
		if (it.c !== _cat) continue;
		if (sub && (_cat === 'weapon' ? it.wt !== sub : !it.loc.includes(sub))) continue;
		if (q && !it._lc.includes(q)) continue;
		if (!isNaN(lv) && it.lv > lv) continue;
		if (job && !it.j.startsWith('Every Job') && !it.j.toLowerCase().includes(job)) continue;
		if (job && it.j.toLowerCase().includes('except ' + job)) continue;
		let hit = null;
		let best = -Infinity;
		let sum = 0;
		if (effFilter) {
			hit = [];
			it.eff.forEach((e, i) => {
				if ((!nocond || !e.c) && matches(e, kinds, target)) {
					hit.push(i);
					const m = magOf(e);
					if (m !== null) {
						if (m > best) best = m;
						sum += m;
					}
				}
			});
			if (!hit.length) continue;
		}
		out.push({ it, hit, best, sum });
	}
	const key = {
		atk: r => r.it.atk || 0,
		matk: r => r.it.matk || 0,
		def: r => r.it.def || 0,
		mdef: r => r.it._mdef,
		wl: r => r.it.wl || 0,
		lv: r => r.it.lv,
		s: r => r.it.s,
		w: r => r.it.w,
		id: r => r.it.id,
		eff: r => (r.best === -Infinity ? -1e9 : r.best)
	}[sort];
	// eff: rank by the strongest matching effect, ties broken by the sum of all matching effects
	const tie = sort === 'eff' ? (a, b) => (a.sum - b.sum) * dir : () => 0;
	if (key) out.sort((a, b) => (key(a) - key(b)) * dir || tie(a, b) || a.it.n.localeCompare(b.it.n));
	else out.sort((a, b) => a.it.n.localeCompare(b.it.n));
	_results = out;
	_page = 0;
	renderPage();
};

function stats(it) {
	const s = [];
	if (it.c === 'weapon') s.push(it.wt, 'ATK ' + it.atk + (it.matk ? ' MATK ' + it.matk : ''), 'Wpn Lv ' + it.wl);
	if (it.c === 'armor') s.push(it.loc.join('/'), 'DEF ' + it.def + (it._mdef ? ' MDEF ' + it._mdef : ''));
	if (it.c === 'card' || it.c === 'enchant') s.push(it.loc.join('/') || 'Card');
	else s.push('Slots ' + it.s);
	s.push('Wt ' + it.w);
	if (it.lv) s.push('Lv ' + it.lv);
	if (it.r === 0) s.push('Unrefinable');
	if (it.mvp) s.push('Slotted MVP version');
	return s.join(' · ');
}

function renderPage() {
	const root = ItemFinder.getRoot();
	const list = root.querySelector('.list');
	const pages = Math.max(1, Math.ceil(_results.length / PAGE));
	_page = Math.min(Math.max(0, _page), pages - 1);
	const slice = _results.slice(_page * PAGE, _page * PAGE + PAGE);
	list.innerHTML = slice
		.map(({ it, hit }) => {
			let effs;
			if (it.d) {
				const shown = new Set();
				effs = it.d
					.map(l => {
						if (l.h) return `<li class="hdr">${esc(stripItemNavi(l.x))}</li>`;
						const isHit = hit && l.b.some(i => hit.includes(i));
						l.b.forEach(i => shown.add(i));
						return `<li class="${isHit ? 'hit' : ''}${l.c ? ' cond' : ''}">${esc(stripItemNavi(l.x))}</li>`;
					})
					.join('');
				// matched bonuses the description does not mention: show the script wording, flagged
				if (hit)
					effs += hit
						.filter(i => !shown.has(i))
						.map(i => `<li class="hit src">${esc(it.eff[i].x)} (from item script)</li>`)
						.join('');
			} else {
				effs = it.eff
					.map(
						(e, i) =>
							`<li class="${hit && hit.includes(i) ? 'hit' : ''}${e.c ? ' cond' : ''}">${esc(e.x)}${e.c ? ' (conditional)' : ''}</li>`
					)
					.join('');
			}
			return (
				`<div class="item" data-id="${it.id}"><div class="icon"></div><div><div class="name">${esc(it.n)}` +
				(it.s && it.c !== 'card' && it.c !== 'enchant' ? ` [${it.s}]` : '') +
				` <span class="stats">#${it.id}</span></div><div class="stats">${esc(stats(it))}</div>` +
				`<div class="stats">${esc(it.j)}</div><ul class="effs">${effs}</ul></div></div>`
			);
		})
		.join('');
	list.scrollTop = 0;
	setStatus(`${_results.length} result(s)`);
	root.querySelector('.page').textContent = `${_page + 1} / ${pages}`;
	slice.forEach(({ it }) => {
		const info = DB.getItemInfo(it.id);
		if (!info || !info.identifiedResourceName) return;
		Client.loadFile(DB.INTERFACE_PATH + 'item/' + info.identifiedResourceName + '.bmp', url => {
			const el = list.querySelector(`.item[data-id="${it.id}"] .icon`);
			if (el) el.style.backgroundImage = `url(${url})`;
		});
	});
}

ItemFinder.init = function init() {
	const root = this.getRoot();
	root.querySelector('.kinds').innerHTML = KINDS.map(
		([k, l]) => `<label><input type="checkbox" value="${k}" /> ${l}</label>`
	).join('');
	root.querySelector('.close').addEventListener('click', () => this.toggle());
	root.querySelectorAll('.tab').forEach(t =>
		t.addEventListener('click', () => {
			root.querySelectorAll('.tab').forEach(x => x.classList.remove('active'));
			t.classList.add('active');
			_cat = t.dataset.cat;
			if (_items) {
				fillSub();
				this.search();
			}
		})
	);
	let timer = null;
	const deb = () => {
		clearTimeout(timer);
		timer = setTimeout(() => this.search(), 150);
	};
	root.querySelectorAll('input, select').forEach(el => {
		el.addEventListener(el.tagName === 'INPUT' && el.type !== 'checkbox' ? 'input' : 'change', deb);
		el.addEventListener('keydown', e => e.stopPropagation());
		el.addEventListener('mousedown', e => e.stopPropagation());
	});
	root.querySelector('.prev').addEventListener('click', () => {
		_page--;
		renderPage();
	});
	root.querySelector('.next').addEventListener('click', () => {
		_page++;
		renderPage();
	});
	root.querySelector('.list').addEventListener('click', e => {
		const row = e.target.closest('.item');
		if (!row) return;
		root.querySelectorAll('.item.sel').forEach(x => x.classList.remove('sel'));
		row.classList.add('sel');
		showDetail(parseInt(row.dataset.id, 10));
	});
	root.querySelector('.dclose').addEventListener('click', () => {
		root.querySelector('.detail').style.display = 'none';
		_detailId = 0;
	});
	const plv = root.querySelector('.plv');
	plv.addEventListener('input', () => _detailId && renderDrops(_detailId));
	plv.addEventListener('keydown', e => e.stopPropagation());
	plv.addEventListener('mousedown', e => e.stopPropagation());
	root.querySelector('.dquest').addEventListener('click', e => {
		const a = e.target.closest('a[data-url]');
		if (a) {
			e.preventDefault();
			window.open(a.dataset.url, '_blank', 'noopener');
		}
	});
	this.draggable('.titlebar');
};

ItemFinder.onAppend = function onAppend() {
	loadData(() => {
		if (!_items) return;
		fillSub();
		this.search();
	});
};

ItemFinder.toggle = function toggle() {
	if (this.__active) this.remove();
	else this.append();
};

ItemFinder.onShortCut = function onShortCut(key) {
	if (key.cmd === 'TOGGLE') this.toggle();
};

ItemFinder.onKeyDown = function onKeyDown(event) {
	if ((event.which === KEYS.ESCAPE || event.key === 'Escape') && this.__active) {
		this.remove();
		event.stopImmediatePropagation();
		return false;
	}
	return true;
};

let _src = null;
let _srcLoading = false;
let _detailId = 0;

function loadSources(cb) {
	if (_src) return cb();
	if (_srcLoading) return;
	_srcLoading = true;
	Client.getFile(
		SOURCES_FILE,
		data => {
			try {
				const txt =
					typeof data === 'string'
						? data
						: new TextDecoder('utf-8').decode(data instanceof ArrayBuffer ? new Uint8Array(data) : data);
				_src = JSON.parse(txt);
			} catch (e) {
				_src = { mobs: {}, drops: {}, quests: {}, penalty: {} };
			}
			_srcLoading = false;
			cb();
		},
		() => {
			_srcLoading = false;
			_src = { mobs: {}, drops: {}, quests: {}, penalty: {} };
			cb();
		}
	);
}

function penaltyMod(mob, plv) {
	if (!plv || !_src.penalty) return 100;
	const rows = _src.penalty[mob.b ? '11' : '12'];
	if (!rows) return 100;
	const d = mob.lv - plv;
	let rate = 100;
	if (d >= 0) {
		for (const [k, r] of rows) if (k >= 0 && d >= k) rate = r;
	} else {
		for (let i = rows.length - 1; i >= 0; i--) {
			const [k, r] = rows[i];
			if (k <= 0 && d <= k) rate = r;
		}
	}
	return rate;
}

function fmtTime(ms) {
	if (!ms) return '';
	const s = Math.round(ms / 1000);
	return s >= 3600 ? (s / 3600).toFixed(s % 3600 ? 1 : 0) + 'h' : s >= 60 ? Math.round(s / 60) + 'm' : s + 's';
}

function renderDrops(id) {
	const root = ItemFinder.getRoot();
	const box = root.querySelector('.ddrops');
	const plv = parseInt(root.querySelector('.plv').value, 10) || 0;
	const it = _byId && _byId.get(id);
	const list = [];
	const add = (iid, tag) => (_src.drops[iid] || []).forEach(([mid, p, mvp]) => list.push({ mid, p, mvp, tag }));
	add(id, '');
	if (it && !it.mvp && _byId.get(id + 40000)) add(id + 40000, 'slotted MVP version');
	const rows = list
		.map(d => {
			const m = _src.mobs[d.mid] || { n: '#' + d.mid, lv: 0, sp: [] };
			let r = d.mvp ? d.p : Math.max(1, Math.floor((d.p * penaltyMod(m, plv)) / 100));
			r = Math.min(r, 10000);
			return { ...d, m, r };
		})
		.sort((a, b) => b.r - a.r);
	if (!rows.length) {
		box.innerHTML = '<div class="drop nospawn">No monster drops this item.</div>';
		return;
	}
	box.innerHTML = rows
		.map(({ m, r, mvp, tag }) => {
			const sp = m.sp.length
				? m.sp
						.map(
							([map, name, c, d]) =>
								`<div class="sp">${esc(name)} (${esc(map)}) ×${c}${d ? ' · respawn ' + fmtTime(d) : ''}</div>`
						)
						.join('')
				: '<div class="sp">No natural spawn (event / summon / instance only)</div>';
			return (
				`<div class="drop${m.sp.length ? '' : ' nospawn'}"><span class="rate">${(r / 100).toFixed(r < 100 ? 2 : 1)}%</span>` +
				`${esc(m.n)} (Lv ${m.lv}${m.mvp ? ', MVP' : m.b ? ', Boss' : ''})${mvp ? ' · MVP reward' : ''}${tag ? ' · ' + esc(tag) : ''}${sp}</div>`
			);
		})
		.join('');
}

function showDetail(id) {
	const root = ItemFinder.getRoot();
	const panel = root.querySelector('.detail');
	const it = _byId && _byId.get(id);
	const info = DB.getItemInfo(id) || {};
	_detailId = id;
	panel.style.display = '';
	const plv = root.querySelector('.plv');
	if (!plv.value && Session.Entity && Session.Entity.clevel) plv.value = Session.Entity.clevel;
	root.querySelector('.dname').textContent =
		(info.identifiedDisplayName || (it && it.n) || '#' + id) +
		(it && it.s && it.c !== 'card' && it.c !== 'enchant' ? ` [${it.s}]` : '');
	const icon = root.querySelector('.dicon');
	const col = root.querySelector('.collection');
	icon.style.backgroundImage = col.style.backgroundImage = 'none';
	if (info.identifiedResourceName) {
		Client.loadFile(
			DB.INTERFACE_PATH + 'item/' + info.identifiedResourceName + '.bmp',
			u => _detailId === id && (icon.style.backgroundImage = `url(${u})`)
		);
		Client.loadFile(
			DB.INTERFACE_PATH + 'collection/' + info.identifiedResourceName + '.bmp',
			u => _detailId === id && (col.style.backgroundImage = `url(${u})`)
		);
	}
	let desc = info.identifiedDescriptionName || '';
	if (Array.isArray(desc)) desc = desc.join('\n');
	desc = stripItemNavi(desc);
	root.querySelector('.ddesc').innerHTML = desc
		? DB.formatMsgToHtml(esc(desc))
		: esc(it ? it.eff.map(e => e.x).join('\n') : '');
	const art = root.querySelector('.dart');
	art.innerHTML = '';
	if (it && it.c === 'card') {
		let illust = info.illustResourcesName;
		if (!illust && id > 30000) illust = (DB.getItemInfo(id - 30000) || {}).illustResourcesName;
		if (illust) {
			art.innerHTML = '<div></div>';
			Client.loadFile(`${DB.INTERFACE_PATH}cardbmp/${illust}.bmp`, u => {
				const d = art.querySelector('div');
				if (d && _detailId === id) d.style.backgroundImage = `url(${u})`;
			});
		}
	}
	root.querySelector('.ddrops').innerHTML = '<div class="drop nospawn">Loading...</div>';
	root.querySelector('.dquest').innerHTML = '';
	loadSources(() => {
		if (_detailId !== id) return;
		const qid = it && it.mvp ? it.mvp : id;
		const q = _src.quests[id] || _src.quests[qid];
		root.querySelector('.dquest').innerHTML = q
			? `<div class="qr"><b>Quest reward</b> — given by NPC scripts: ${q.map(f => esc(f.replace(/^npc\//, '').replace(/\.txt$/, ''))).join(', ')}<br/>` +
				`<a href="#" data-url="${RMS_URL(qid)}">RateMyServer renewal item page (quest guides under “Obtainable From”)</a></div>`
			: '';
		renderDrops(id);
		root.querySelector('.dbody').scrollTop = 0;
	});
}

ItemFinder.showDetail = showDetail;

export default UIManager.addComponent(ItemFinder);
